(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1x = Math.sin(y * 0.012 - t * 0.15) * 20 + Math.cos(x * 0.008 + t * 0.1) * 15;
  const warp1y = Math.cos(x * 0.012 + t * 0.12) * 20 + Math.sin(y * 0.009 - t * 0.18) * 15;
  const warp2x = Math.sin((x + y) * 0.006 + t * 0.08) * 12;
  const warp2y = Math.cos((x - y) * 0.007 - t * 0.09) * 12;
  const sx = x + warp1x + warp2x, sy = y + warp1y + warp2y;
  const src = [
    [120+Math.sin(t*0.4)*90, 60+Math.cos(t*0.35)*40, 0.07, 2.1, 1.0],
    [360+Math.cos(t*0.45)*90, 180+Math.sin(t*0.4)*40, 0.09, 1.8, 0.8],
    [240+Math.sin(t*0.25+2)*130, 120+Math.cos(t*0.4+1)*80, 0.055, 2.4, 1.2],
    [60+Math.cos(t*0.7+1)*70, 190+Math.sin(t*0.5+3)*50, 0.11, 1.6, 0.7],
    [420+Math.sin(t*0.35+4)*80, 50+Math.cos(t*0.8+2)*60, 0.065, 2.7, 0.9],
    [200+Math.cos(t*0.3+5)*100, 220+Math.sin(t*0.5)*70, 0.08, 2.0, 1.1],
    [300+Math.sin(t*0.55+3)*60, 30+Math.cos(t*0.65+1)*50, 0.1, 1.9, 0.85],
    [180+Math.cos(t*0.38+2)*110, 140+Math.sin(t*0.42)*90, 0.048, 2.5, 1.3]
  ];
  let aS = 0, iS = 0, wSum = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx - sX) ** 2 + (sy - sY) ** 2);
    const decay = 1.0 / (1.0 + d * 0.003);
    aS += Math.sin(d * f - t * sp) * decay * w;
    iS += Math.sin(d * f * 0.65 + t * sp * 0.55 + 1.7) * decay * w;
    wSum += w * decay;
  }
  aS /= wSum; iS /= wSum;
  const dist = Math.sqrt((sx - cx) ** 2 + (sy - cy) ** 2);
  const ang = Math.atan2(sy - cy, sx - cx);
  const spiral1 = Math.sin(dist * 0.045 - ang * 3 - t * 1.3) * Math.exp(-dist * 0.003);
  const spiral2 = Math.sin(dist * 0.035 + ang * 4.5 - t * 0.9 + 0.5) * Math.exp(-dist * 0.004);
  const spiral3 = Math.sin(dist * 0.06 - ang * 2 - t * 1.8 + 1.2) * Math.exp(-dist * 0.005);
  const spiral = (spiral1 + spiral2 + spiral3) * 0.35;
  const bg1 = Math.sin(sx * 0.035 + sy * 0.02 + t * 0.7);
  const bg2 = Math.sin(sx * 0.025 - sy * 0.035 + t * 0.95);
  const bg3 = Math.sin((sx + sy) * 0.1 + t * 2.2) * 0.25;
  const bg4 = Math.sin((sx - sy) * 0.08 - t * 1.8) * 0.2;
  const bg = (bg1 + bg2) * 0.5 + bg3 + bg4;
  const fbm1 = Math.sin(sx * 0.02 + t * 0.3) * Math.sin(sy * 0.025 - t * 0.2);
  const fbm2 = Math.sin(sx * 0.04 + sy * 0.03 + t * 0.5) * 0.5;
  const fbm3 = Math.sin(sx * 0.08 - sy * 0.06 + t * 0.8) * 0.25;
  const fbm = (fbm1 + fbm2 + fbm3) * 0.4;
  const cross = Math.sin(aS * Math.PI * 2) * Math.cos(iS * Math.PI * 1.5) * 0.3;
  const reaction = Math.tanh((aS - iS * 0.65 + bg * 0.25 + spiral + fbm + cross) * 2.0);
  const cellX = Math.sin(sx * 0.18) * Math.sin(sy * 0.18);
  const cellY = Math.sin(sx * 0.12 + sy * 0.14 + t * 0.4);
  const cell = Math.tanh((cellX + cellY * 0.5) * 1.8) * 0.2;
  const edge = reaction - cell * 0.5;
  const detail = Math.sin(sx * 0.3 + reaction * 3) * Math.sin(sy * 0.3 - reaction * 2.5) * 0.08 * (1.0 - Math.abs(reaction));
  const blend = edge + detail;
  const v = blend * 0.5 + 0.5;
  const pal = [
    [5, 12, 52], [10, 40, 85], [12, 75, 105], [18, 120, 125],
    [45, 155, 130], [130, 180, 95], [200, 185, 60], [215, 145, 55],
    [195, 95, 60], [165, 55, 65], [120, 35, 60], [70, 22, 55], [5, 12, 52]
  ];
  const idx = v * (pal.length - 1);
  const i = Math.min(idx | 0, pal.length - 2);
  const f = idx - i;
  const lum = 0.85 + Math.sin(reaction * Math.PI) * 0.15;
  const glow = Math.exp(-Math.abs(reaction) * 2) * 0.15;
  const edgeBoost = Math.abs(reaction) > 0.65 ? 1.12 : 1.0;
  const totalLum = lum * edgeBoost + glow;
  return [
    Math.min(255, (pal[i][0] + (pal[i + 1][0] - pal[i][0]) * f) * totalLum) | 0,
    Math.min(255, (pal[i][1] + (pal[i + 1][1] - pal[i][1]) * f) * totalLum) | 0,
    Math.min(255, (pal[i][2] + (pal[i + 1][2] - pal[i][2]) * f) * totalLum) | 0
  ];
}
